import{_ as n,C as r,o as d,c as l,j as t,a,G as i,aj as s}from"./chunks/framework.BwH0p-pt.js";const y=JSON.parse('{"title":"Linking Products","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/associations/linking-products.md","filePath":"3.0/associations/linking-products.md","lastUpdated":1785836850000}'),c={name:"3.0/associations/linking-products.md"};function h(p,e,u,g,k,m){const o=r("ImagePopup");return d(),l("div",null,[e[0]||(e[0]=t("h1",{id:"linking-products",tabindex:"-1"},[a("Linking Products "),t("a",{class:"header-anchor",href:"#linking-products","aria-label":'Permalink to "Linking Products"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("You attach associated products on the "),t("strong",null,"product edit page"),a(". Open a product and find the "),t("strong",null,"Associations"),a(" card — it shows how many products are already linked. Click it and the Associations panel slides open as a drawer over the page.")],-1)),i(o,{src:"/assets/3.0/images/associations/associations-drawer.png",alt:"Associations drawer on the product edit page"}),e[2]||(e[2]=s('<h2 id="add-links" tabindex="-1">Add links <a class="header-anchor" href="#add-links" aria-label="Permalink to &quot;Add links&quot;">​</a></h2><ol><li>Open the product and click the <strong>Associations</strong> card.</li><li>If the type you want is not shown yet, click <strong>Add Association Type</strong> and search for it by name or code. Only enabled types are offered.</li><li>Each type is a tab, with a badge showing how many products it holds. Select the tab you want to work in.</li><li>Click <strong>Add</strong>. The product picker opens — the full product grid, with the same search, filters and sorting you know from the catalog. Products already linked under this type are not offered again.</li><li>Tick the products to link and confirm.</li><li>Click <strong>Add Selected</strong> to close the drawer, then save the product.</li></ol>',2)),i(o,{src:"/assets/3.0/images/associations/associations-product-picker.png",alt:"Product picker for selecting associated products"}),e[3]||(e[3]=s('<h2 id="fill-the-link-fields" tabindex="-1">Fill the link fields <a class="header-anchor" href="#fill-the-link-fields" aria-label="Permalink to &quot;Fill the link fields&quot;">​</a></h2><p>If the association type defines <a href="./association-types.html#custom-fields-on-each-link">custom fields</a>, they appear next to every linked product — text boxes and Yes/No switches. Fields marked <em>per locale</em> show a badge with the current catalog language: the value you type belongs to that language, and you switch the language at the top of the page to fill another one.</p><h2 id="remove-a-link" tabindex="-1">Remove a link <a class="header-anchor" href="#remove-a-link" aria-label="Permalink to &quot;Remove a link&quot;">​</a></h2><p>Click <strong>Remove Product</strong> under the product you want to unlink, then save. Removing a link never touches the product itself.</p><h2 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h2><p>The drawer feeds the normal product form. As soon as you change anything — add, remove, or edit a field value — the <strong>Save / Discard</strong> bar appears at the bottom of the page. Nothing is stored until you click <strong>Save</strong>, and <strong>Discard</strong> puts everything back the way it was. Leaving the page with unsaved changes triggers a warning first.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Disabling an association type hides its tab from the drawer, but the links it holds are kept and continue to export. Re-enable the type and they reappear.</p></div><h2 id="beyond-the-edit-page" tabindex="-1">Beyond the edit page <a class="header-anchor" href="#beyond-the-edit-page" aria-label="Permalink to &quot;Beyond the edit page&quot;">​</a></h2><ul><li><strong>Import and export</strong> — associations travel inside the normal product <a href="./../data-transfer/import.html">import</a> and <a href="./../data-transfer/export.html">export</a>, and dedicated association jobs exist for moving links in bulk on their own.</li><li><strong>Integrations</strong> — every linked product, including custom field values, is part of the product data your connected systems receive through the API.</li></ul>',9))])}const b=n(c,[["render",h]]);export{y as __pageData,b as default};
